initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Entity Attributes with Response Status Code set to 400     and
        Update Entity Attributes with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/InvalidRequest'     and
        Update Entity Attributes with Response body containing 'title' element
}
